import React, { useState } from 'react';

const CHIPS = ['All', 'Active', 'Archived', 'Starred'] as const;
type Chip = (typeof CHIPS)[number];

const styles = `
@layer components {
  :root {
    --shelf-chip-bgColor-default: #f0f0f0;
    --shelf-chip-bgColor-pressed: #1a1a2e;
    --shelf-chip-fgColor-default: #1a1a2e;
    --shelf-chip-fgColor-pressed: #ffffff;
    --shelf-chip-borderColor-default: #cccccc;
    --shelf-chip-borderColor-pressed: #1a1a2e;
  }

  [data-theme="dark"],
  @media (prefers-color-scheme: dark) {
    :root {
      --shelf-chip-bgColor-default: #2a2a3e;
      --shelf-chip-bgColor-pressed: #ffffff;
      --shelf-chip-fgColor-default: #ffffff;
      --shelf-chip-fgColor-pressed: #1a1a2e;
      --shelf-chip-borderColor-default: #555577;
      --shelf-chip-borderColor-pressed: #ffffff;
    }
  }

  .chip-bar {
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
    padding: 0;
    list-style: none;
  }

  .chip-button {
    appearance: none;
    background-color: var(--shelf-chip-bgColor-default);
    color: var(--shelf-chip-fgColor-default);
    border: 1px solid var(--shelf-chip-borderColor-default);
    border-radius: 9999px;
    padding: 4px 16px;
    cursor: pointer;
    font: inherit;
  }

  .chip-button[aria-pressed="true"] {
    background-color: var(--shelf-chip-bgColor-pressed);
    color: var(--shelf-chip-fgColor-pressed);
    border-color: var(--shelf-chip-borderColor-pressed);
  }
}
`;

export function ChipFilter(): React.ReactElement {
  const [pressed, setPressed] = useState<Chip>('All');

  return (
    <>
      <style>{styles}</style>
      <ul className="chip-bar" role="list">
        {CHIPS.map((chip) => (
          <li key={chip}>
            <button
              type="button"
              className="chip-button"
              aria-pressed={pressed === chip}
              onClick={() => setPressed(chip)}
            >
              {chip}
            </button>
          </li>
        ))}
      </ul>
    </>
  );
}
